sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float lines;
uniform float intensity;
uniform float maskType;
uniform float maskStrength;
uniform float curvature;
uniform float rgbShift;
uniform float bloom;
uniform float vignette;
uniform float flicker;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 uv = coord / size;
    float2 d = (uv - 0.5) * 2.0;
    d *= 1.0 + curvature * dot(d, d) * 0.25;
    float2 uv2 = d * 0.5 + 0.5;
    float inb = step(0.0, uv2.x) * step(uv2.x, 1.0) * step(0.0, uv2.y) * step(uv2.y, 1.0);
    float2 p = uv2 * size;
    float3 col = float3(tex(p + float2(rgbShift, 0.0)).r, tex(p).g, tex(p - float2(rgbShift, 0.0)).b);
    float3 bl = (tex(p + float2(3.0, 0.0)).rgb + tex(p - float2(3.0, 0.0)).rgb + tex(p + float2(0.0, 3.0)).rgb + tex(p - float2(0.0, 3.0)).rgb) * 0.25;
    col += bl * bloom * 0.6;
    float sl = 0.5 + 0.5 * sin(uv2.y * lines * 6.2831853);
    col *= 1.0 - intensity * (1.0 - sl);
    float m = mod(floor(coord.x), 3.0);
    float3 mk = m < 0.5 ? float3(1.0, 1.0 - maskStrength, 1.0 - maskStrength) : (m < 1.5 ? float3(1.0 - maskStrength, 1.0, 1.0 - maskStrength) : float3(1.0 - maskStrength, 1.0 - maskStrength, 1.0));
    if (maskType > 1.5) mk *= 1.0 - maskStrength * 0.5 * step(0.5, fract(floor(coord.y / 2.0) * 0.5 + floor(coord.x / 3.0) * 0.5));
    if (maskType > 0.5) col *= mk;
    col *= 1.0 - vignette * dot(d, d) * 0.35;
    col *= 1.0 + flicker * sin(time * 60.0);
    return fin(c, float4(saturate(col) * c.a * inb, c.a * inb), opacity);
}
